-- ============================================
-- LUMA — Enrichissement Thématique 10 (Enquête policière) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"suspect1": "suspect A", "suspect2": "suspect B", "real": "le vrai coupable"}, "start_node": "n1", "nodes": {"n1": {"speaker": "suspect1", "text": "It wasn''t me! I had every reason to want him gone, sure, but I didn''t do it!", "text_fr": "Ce n''était pas moi ! J''avais toutes les raisons de vouloir qu''il disparaisse, certes, mais je ne l''ai pas fait !", "choices": [{"text": "Where were you at the time of the incident?", "next": "n2"}, {"text": "What exactly was your motive against him?", "next": "n2b"}]}, "n2": {"speaker": "suspect1", "text": "At a bar, dozens of people saw me.", "text_fr": "Dans un bar, des dizaines de gens m''ont vu.", "choices": [{"text": "That alibi checks out. Let''s look elsewhere.", "next": "n3"}]}, "n2b": {"speaker": "suspect1", "text": "He fired me last year, cost me everything. But that''s not enough to kill someone!", "text_fr": "Il m''a viré l''an dernier, ça m''a coûté tout. Mais ce n''est pas suffisant pour tuer quelqu''un !", "choices": [{"text": "Where were you at the time it happened?", "next": "n2"}]}, "n3": {"speaker": "suspect2", "text": "You think it was me? I barely knew the guy!", "text_fr": "Vous pensez que c''était moi ? Je le connaissais à peine !", "choices": [{"text": "Your fingerprints were found at the scene, though.", "next": "n4"}, {"text": "Then why does your name appear in his appointment book?", "next": "n4b"}]}, "n4": {"speaker": "suspect2", "text": "I was there earlier that day for a delivery, that''s all!", "text_fr": "J''étais là plus tôt dans la journée pour une livraison, c''est tout !", "choices": [{"text": "That also checks out. There must be someone else.", "next": "n5"}]}, "n4b": {"speaker": "suspect2", "text": "(nervous) Fine — we had a meeting scheduled, about a business dispute. That''s all.", "text_fr": "(nerveux) Bon — on avait rendez-vous, pour un litige commercial. C''est tout.", "choices": [{"text": "A dispute doesn''t rule you out entirely. Let''s verify your alibi too.", "next": "n5"}]}, "n5": {"speaker": "real", "text": "(nervously) I... I can explain everything.", "text_fr": "(nerveusement) Je... je peux tout expliquer.", "choices": [{"text": "Your story doesn''t match the evidence. It was you, wasn''t it?", "next": "n6"}, {"text": "Let''s start simple — where were you that night?", "next": "n6b"}]}, "n6": {"speaker": "real", "text": "(breaks down) Yes... it was me. I panicked.", "text_fr": "(craque) Oui... c''était moi. J''ai paniqué.", "choices": [{"text": "Tell me exactly what happened.", "next": "end_solved"}]}, "n6b": {"speaker": "real", "text": "(hesitates, then the story starts falling apart under questioning)", "text_fr": "(hésite, puis l''histoire s''effondre sous l''interrogatoire)", "choices": [{"text": "Your story just contradicted itself. It''s over — confess.", "next": "end_solved"}]}, "end_solved": {"speaker": "real", "text": "It was an accident, but I panicked and tried to hide it. I''m sorry.", "text_fr": "C''était un accident, mais j''ai paniqué et j''ai essayé de le cacher. Je suis désolé.", "end": true, "ending_label": "Vrai coupable démasqué après une enquête minutieuse 🎯"}}}'::jsonb, is_playable = true
where title = 'Une enquête complète avec plusieurs faux coupables'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"friend": "ton ami proche"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "I know how this looks, but you have to believe me, I had nothing to do with it.", "text_fr": "Je sais comment ça a l''air, mais tu dois me croire, je n''ai rien à voir avec ça.", "choices": [{"text": "I want to believe you, but I have to follow the evidence.", "next": "n2"}, {"text": "I trust you completely — let''s find the real truth together.", "next": "n2b"}, {"text": "Honestly, the evidence against you is troubling.", "next": "n2c"}]}, "n2": {"speaker": "friend", "text": "I understand... do what you have to do.", "text_fr": "Je comprends... fais ce que tu dois faire.", "choices": [{"text": "Let''s go through everything carefully, for your sake.", "next": "n3"}]}, "n2b": {"speaker": "friend", "text": "Thank you... that means everything to me right now.", "text_fr": "Merci... ça compte énormément pour moi en ce moment.", "choices": [{"text": "Let''s clear your name properly.", "next": "n3"}]}, "n2c": {"speaker": "friend", "text": "(hurt) I thought you of all people would trust me.", "text_fr": "(blessé) Je pensais que toi entre tous me ferais confiance.", "choices": [{"text": "I do trust you — I''m just being thorough for your protection.", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "There''s something I didn''t tell you — I was at the scene that night, but only briefly.", "text_fr": "Il y a quelque chose que je ne t''ai pas dit — j''étais sur les lieux cette nuit-là, mais brièvement.", "choices": [{"text": "Why didn''t you tell me sooner?", "next": "n4"}, {"text": "What were you doing there? Tell me everything now.", "next": "n4b"}]}, "n4": {"speaker": "friend", "text": "I was scared it would make me look guilty. I should have trusted you from the start.", "text_fr": "J''avais peur que ça me fasse paraître coupable. J''aurais dû te faire confiance dès le début.", "choices": [{"text": "It''s okay, let''s use this honestly now to find the truth.", "next": "n5"}]}, "n4b": {"speaker": "friend", "text": "I saw someone leaving through the back door — I was too afraid to mention it before.", "text_fr": "J''ai vu quelqu''un sortir par la porte arrière — j''avais trop peur pour le mentionner avant.", "choices": [{"text": "That''s crucial. Describe them in detail.", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "(later, new evidence surfaces) You found it — proof I was set up!", "text_fr": "(plus tard, une nouvelle preuve apparaît) Tu l''as trouvée — la preuve que j''ai été piégé !", "choices": [{"text": "I never gave up on finding the truth.", "next": "end_cleared"}, {"text": "Your honesty in the end made all the difference.", "next": "end_honest"}]}, "end_cleared": {"speaker": "friend", "text": "I''ll never forget what you did for me.", "text_fr": "Je n''oublierai jamais ce que tu as fait pour moi.", "end": true, "ending_label": "Innocence prouvée 💙"}, "end_honest": {"speaker": "friend", "text": "You''re right — I learned that honesty, even when scary, is what saved me.", "text_fr": "Tu as raison — j''ai appris que l''honnêteté, même effrayante, est ce qui m''a sauvé.", "end": true, "ending_label": "Vérité et honnêteté triomphent 🕊️"}}}'::jsonb, is_playable = true
where title = 'Une affaire qui implique un proche du personnage'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"judge": "la juge", "lawyer": "l''avocat de la défense"}, "start_node": "n1", "nodes": {"n1": {"speaker": "judge", "text": "Detective, please present your final conclusion to the court.", "text_fr": "Détective, veuillez présenter votre conclusion finale au tribunal.", "choices": [{"text": "Based on the timeline and physical evidence, the defendant is guilty.", "next": "n2"}, {"text": "The evidence points to reasonable doubt — I cannot conclude guilt.", "next": "n2b"}]}, "n2": {"speaker": "judge", "text": "A bold conclusion. Can you walk the court through your reasoning?", "text_fr": "Une conclusion audacieuse. Pouvez-vous détailler votre raisonnement au tribunal ?", "choices": [{"text": "(present the timeline, fingerprints, and witness testimony clearly)", "next": "n3"}]}, "n2b": {"speaker": "judge", "text": "A careful stance. Explain the gaps you found in the evidence.", "text_fr": "Une position prudente. Expliquez les failles que vous avez trouvées dans les preuves.", "choices": [{"text": "(explain the inconsistencies and alternative explanations)", "next": "n3b"}]}, "n3": {"speaker": "lawyer", "text": "Objection — the witness testimony was unreliable, wasn''t it?", "text_fr": "Objection — le témoignage était peu fiable, n''est-ce pas ?", "choices": [{"text": "The witness was corroborated by independent camera footage.", "next": "n4"}, {"text": "I acknowledge some uncertainty, but the overall pattern remains clear.", "next": "n4b"}]}, "n3b": {"speaker": "lawyer", "text": "So you admit the evidence isn''t conclusive either way?", "text_fr": "Donc vous admettez que les preuves ne sont concluantes ni dans un sens ni dans l''autre ?", "choices": [{"text": "Correct — which is exactly why reasonable doubt applies here.", "next": "n4c"}]}, "n4": {"speaker": "judge", "text": "That''s compelling corroboration. The court will consider this carefully.", "text_fr": "C''est une corroboration convaincante. Le tribunal en tiendra compte avec attention.", "choices": [{"text": "(await the verdict)", "next": "end_guilty"}]}, "n4b": {"speaker": "judge", "text": "I appreciate your honesty about the uncertainty, detective.", "text_fr": "J''apprécie votre honnêteté sur l''incertitude, détective.", "choices": [{"text": "(await the verdict)", "next": "end_close"}]}, "n4c": {"speaker": "judge", "text": "A principled stance, even against pressure to conclude otherwise.", "text_fr": "Une position de principe, même sous la pression de conclure autrement.", "choices": [{"text": "(await the verdict)", "next": "end_doubt"}]}, "end_guilty": {"speaker": "judge", "text": "The evidence is compelling. The court finds the defendant guilty.", "text_fr": "Les preuves sont convaincantes. Le tribunal déclare l''accusé coupable.", "end": true, "ending_label": "Verdict de culpabilité obtenu ⚖️"}, "end_close": {"speaker": "judge", "text": "Given the balance of evidence, though imperfect, the court finds the defendant guilty by a narrow margin.", "text_fr": "Compte tenu de l''équilibre des preuves, bien qu''imparfait, le tribunal déclare l''accusé coupable de justesse.", "end": true, "ending_label": "Verdict serré mais rendu ⚖️"}, "end_doubt": {"speaker": "judge", "text": "Given the reasonable doubt presented, the court finds the defendant not guilty.", "text_fr": "Compte tenu du doute raisonnable présenté, le tribunal déclare l''accusé non coupable.", "end": true, "ending_label": "Justice rendue avec prudence ⚖️"}}}'::jsonb, is_playable = true
where title = 'Un procès final où l''utilisateur plaide sa déduction'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
